import secrets
from django.contrib.auth import get_user_model
from django.core.management.base import BaseCommand
from blog.models import Post

class Command(BaseCommand):
    help = 'Ajoute des articles de démonstration et un compte administrateur local.'

    def handle(self, *args, **options):
        user, created = get_user_model().objects.get_or_create(username='louis', defaults={'is_staff': True, 'is_superuser': True})
        if created:
            password = secrets.token_urlsafe(12)
            user.set_password(password)
            user.save()
            self.stdout.write(f'Compte local : louis\nMot de passe : {password}')
        data = [
            ('Le gâteau qui voulait devenir un cookie.', 'Un cœur fondant ? Plutôt un cœur absent. Chronique d’un gâteau au chocolat un peu trop sûr de lui.', 'sucre', 4, 45, 'photo-1578985545062-69928b1d9587', 'J’avais promis un gâteau haut, moelleux et généreux. J’ai sorti le beurre, le chocolat et un moule probablement trop grand. Jusque-là, tout allait bien.\n\nPuis j’ai décidé que la levure n’était pas indispensable. Après tout, le chocolat allait faire le travail, non ? Quarante-cinq minutes plus tard, le four m’a rendu une grande galette avec une croûte un peu trop convaincante.\n\nOn l’a découpée en petits morceaux et servie avec du yaourt. Personne n’a demandé une deuxième part, mais tout le monde a ri. Une réussite sociale, à défaut d’une réussite pâtissière.', 'Vérifier la taille du moule. Et quand la recette dit une cuillère de levure, elle a peut-être une bonne raison.'),
            ('Mon pain a le sens de la gravité.', 'Une croûte prometteuse, une mie qui fait de la résistance. Le premier pain maison laisse des traces.', 'boulange', 5, 180, 'photo-1509440159596-0249088772ff', 'Dimanche matin : je me lance dans un pain maison. Je pétris avec enthousiasme, je couvre le saladier et j’attends. Trente minutes plus tard, rien.\n\nJ’ai mis la levure dans une eau bien trop chaude. Le pain, lui, a quand même fait son voyage au four. Résultat : une miche très compacte, idéale pour caler une porte.\n\nLa croûte était belle. La découpe, sportive. On a fini par faire des croûtons, et là, il a enfin trouvé sa vocation.', 'Une eau tiède, pas brûlante, pour la levure. Et la patience fait vraiment partie des ingrédients.'),
            ('Les pâtes « al dente », version béton.', 'Cinq minutes de distraction. Une casserole en moins. Un grand moment de solitude.', 'sale', 3, 25, 'photo-1551183053-bf91a1d81141', 'La recette semblait simple : faire bouillir de l’eau, ajouter les pâtes, patienter. J’ai réussi les deux premières étapes avec brio.\n\nPuis le téléphone a sonné. L’eau s’est évaporée et les pâtes ont décidé de ne plus quitter le fond de la casserole. On a tenté la négociation à la spatule, sans succès.\n\nLe dîner s’est transformé en tartines. Rapide, efficace, et nettement moins bruyant à manger.', 'Mettre un minuteur. Le téléphone sait attendre, une casserole sur le feu beaucoup moins.'),
            ('Une tarte tatin… presque retournée.', 'Tout était sous contrôle. Jusqu’au moment du retournement. Le sol s’en souvient encore.', 'sucre', 4, 60, 'photo-1535920527002-b35e96722eb9', 'J’avais choisi les plus belles pommes et préparé un caramel ambré. Même la pâte semblait coopérer.\n\nLe retournement devait être le grand final. Mais j’ai utilisé une assiette plus petite que le moule. Le caramel a pris un chemin personnel et deux pommes se sont échappées.\n\nOn a récupéré ce qui était resté sur l’assiette et appelé ça un dessert déstructuré. C’était bon. Le ménage, moins.', 'Tester l’assiette sur le moule avant de commencer, et laisser tiédir le caramel avant de retourner.'),
            ('Le risotto qui a bu tout le bouillon.', 'Crémeux dans mes rêves. Compact dans l’assiette. Une expérience très… attachante.', 'sale', 3, 50, 'photo-1473093295043-cdd812d0e601', 'J’ai cru qu’un risotto pouvait cuire tranquillement pendant que je préparais autre chose. Le riz a une autre opinion de la question.\n\nQuand je suis revenu, il avait absorbé le bouillon, l’eau et probablement un peu de mon optimisme. Une masse compacte occupait la casserole.\n\nAvec du parmesan et beaucoup de bonne volonté, le dîner a été sauvé. Le lendemain, les restes sont devenus des galettes franchement meilleures que le plat original.', 'Ajouter le bouillon petit à petit, remuer régulièrement et garder le risotto à l’œil.'),
            ('Le jour où j’ai tenté les pancakes verts.', 'Une idée saine, une couleur suspecte, et un petit-déjeuner dont on parle encore.', 'experience', 2, 20, 'photo-1528207776546-365bb710ee93', 'L’idée : ajouter des épinards aux pancakes pour un petit-déjeuner original. Le problème : j’ai mis la moitié du sachet au lieu d’une poignée.\n\nLa pâte avait une couleur spectaculaire. Les pancakes, une texture qui évoquait davantage une éponge que le brunch du dimanche.\n\nUn peu de fromage et un œuf ont changé la donne. En version salée, c’était presque une découverte. Presque.', 'Goûter la pâte avant de tout cuire et commencer par de petites quantités pour les expériences.'),
        ]
        for title, excerpt, category, disaster, minutes, photo, content, lesson in reversed(data):
            Post.objects.get_or_create(title=title, defaults=dict(excerpt=excerpt, category=category, disaster=disaster, minutes=minutes, image_url=f'https://images.unsplash.com/{photo}?auto=format&fit=crop&w=1200&q=85', content=content, lesson=lesson, published=True))
        self.stdout.write(self.style.SUCCESS('6 exemples prêts. Les photos illustrent les articles de démonstration.'))
